    flag := 1;
  ELSIF arg1 < 25 THEN
    OPEN c2;
    flag := 2;
  ELSIF arg1 < 40 THEN
    OPEN c3;
    flag := 3;
  ELSE
    OPEN c4;
    flag := 4;
  END IF;

  IF flag IN (2, 3, 4) THEN
    IF flag = 2 THEN
      LOOP
        FETCH c2 INTO rec2;
        EXIT WHEN c2%NOTFOUND;

        row_count := ROUND(row_count + 1);

        -- Change request: per restaurant-type row processing
        IF rec2."ResTypeID" < 50 THEN
          -- Existing completed-name handling
          UPDATE "Restaurant_Type" SET "ResTypeName" = 'COMPLETED' WHERE CURRENT OF c2;

          -- New: remove every assignment of that type to a restaurant whose rating is below arg5
          DELETE FROM "Type_Of_Restaurant"
           WHERE "ResTypeID" = rec2."ResTypeID"
             AND "ResID" IN (SELECT r."ResID" FROM "Restaurant" r WHERE r."Rating" < arg5);
        ELSE
          -- New: accumulate type id and set description to 'CONTRIBUTED'
          temp_num := temp_num + rec2."ResTypeID";
          UPDATE "Restaurant_Type" SET "ResTypeDescription" = 'CONTRIBUTED' WHERE CURRENT OF c2;
        END IF;
      END LOOP;
      CLOSE c2;

    ELSIF flag = 3 THEN
      LOOP
        FETCH c3 INTO rec3;
        EXIT WHEN c3%NOTFOUND;

        row_count := ROUND(row_count + 1);

        IF rec3."Rating" > 100 THEN
          temp_text := 'OVER_LIMIT';
        ELSIF rec3."Rating" > 50 THEN
          temp_text := 'WITHIN_RANGE';
        ELSE
          temp_text := 'BELOW_MIN';
        END IF;
      END LOOP;
      CLOSE c3;

    ELSIF flag = 4 THEN
      LOOP
        FETCH c4 INTO rec4;
        EXIT WHEN c4%NOTFOUND;

        row_count := ROUND(row_count + 1);

        -- Change request: per-student processing
        IF MOD(rec4."Major", 2) = 0 THEN
          temp_num := temp_num + 1;

          IF rec4."Sex" = arg2 THEN
            IF rec4."Advisor" = 1121 THEN
              DELETE FROM "Visits_Restaurant" WHERE "StuID" = rec4."StuID";
            ELSIF rec4."Advisor" = 7712 THEN
              UPDATE "Student" SET "Age" = "Age" + 1 WHERE "StuID" = rec4."StuID";
            ELSE
              UPDATE "Student" SET "city_code" = 'BAL' WHERE "StuID" = rec4."StuID";
            END IF;
          END IF;
        END IF;
      END LOOP;
      CLOSE c4;
    END IF;
  END IF;

  -- Closeout reckoning (existing structure; now uses updated accumulators)
  IF flag = 1 THEN
    DELETE FROM "Restaurant_Type" WHERE "ResTypeID" < arg3;
  ELSIF flag = 2 AND temp_num > 100 THEN
    UPDATE "Restaurant" SET "Rating" = "Rating" - 10 WHERE "Rating" > 200;
  ELSIF flag = 3 AND temp_text = 'OVER_LIMIT' THEN
    DELETE FROM "Restaurant" WHERE "Rating" > 150;
  ELSIF flag = 4 AND temp_num > 5 THEN
    UPDATE "Student" SET "Sex" = 'PROCESSED' WHERE "Major" < arg1;
  ELSE
    UPDATE "Restaurant_Type" SET "ResTypeName" = 'DEFAULT' WHERE "ResTypeID" IS NULL;
  END IF;
END sp;
